param([int]$Port=18083,[int[]]$Scenarios=@(1,3,5,10))
$ErrorActionPreference='Stop'; $video=Join-Path $env:TEMP 'youtube-unit-qa-videos\v720.mp4'; $root=Join-Path $env:TEMP 'youtube-unit-concurrency'; New-Item -ItemType Directory -Force $root|Out-Null
foreach($n in $Scenarios){$dir=Join-Path $root "clients-$n";New-Item -ItemType Directory -Force $dir|Out-Null;$jobs=1..$n|%{Start-Job -ScriptBlock {param($p,$f,$o) $sw=[Diagnostics.Stopwatch]::StartNew();$body=curl.exe -sS -w "`nHTTP:%{http_code}`nTIME:%{time_total}" -X POST -F "file=@$f;type=video/mp4" -F 'origin=concorrencia' -F 'permission=sintetico' -F 'profiles=360p' "http://127.0.0.1:$p/videos";$sw.Stop();$body} -ArgumentList $Port,$video};$res=$jobs|Receive-Job -Wait -AutoRemoveJob;$res|Set-Content (Join-Path $dir results.txt);[pscustomobject]@{clients=$n;accepted=($res|sls 'HTTP:202').Count;rejected=($res|sls 'HTTP:429').Count}|ConvertTo-Json|Set-Content (Join-Path $dir summary.json);Write-Output "clients=$n accepted=$(($res|sls 'HTTP:202').Count) rejected=$(($res|sls 'HTTP:429').Count)"}
